const std = @import("std");
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const AutoHashMap = std.AutoHashMap;
const Sha256 = std.crypto.hash.sha2.Sha256;
const Complex = std.math.Complex;
const math = std.math;

pub const QuantumLatticeConfig = struct {
    const MAX_BOSONIC_MODES: usize = 256;
    const LATTICE_DEPTH: usize = 8;
    const FLOQUET_PERIODS: usize = 1;
    const ERROR_THRESHOLD: f64 = 1e-12;
    const COHERENCE_TIME_NS: u64 = 1_000_000;
    const GATE_FIDELITY_TARGET: f64 = 0.999999;
};

pub const BosonicMode = struct {
    id: u32,
    displacement: Complex,
    squeezing: Complex,
    photon_number: f64,
    coherence_time_ns: u64,
    error_syndrome: [4]u8,
    entanglement_map: AutoHashMap(u32, f64, std.hash_map.DefaultHashContext(u32), Allocator),

    const Self = @This();

    pub fn init(allocator: Allocator, id: u32) !Self {
        return Self{
            .id = id,
            .displacement = Complex{.re = 0.0, .im = 0.0},
            .squeezing = Complex{.re = 1.0, .im = 0.0},
            .photon_number = 0.0,
            .coherence_time_ns = QuantumLatticeConfig.COHERENCE_TIME_NS,
            .error_syndrome = [_]u8{0, 0, 0, 0},
            .entanglement_map = AutoHashMap(u32, f64).init(allocator),
        };
    }

    pub fn deinit(self: *Self) void {
        self.entanglement_map.deinit();
    }

    fn applyDisplacement(self: *Self, alpha: Complex) void {
        self.displacement.re += alpha.re;
        self.displacement.im += alpha.im;
        self.photon_number = self.displacement.re * self.displacement.re + self.displacement.im * self.displacement.im;
    }

    fn applySqueezing(self: *Self, zeta: Complex) void {
        const r = @sqrt(zeta.re * zeta.re + zeta.im * zeta.im);
        const phi = @atan2(zeta.im, zeta.re);
        const cosh_r = @cosh(r);
        const sinh_r = @sinh(r);
        self.squeezing.re = cosh_r;
        self.squeezing.im = sinh_r * @cos(phi);
    }
};

pub const QuantumLatticeGate = struct {
    gate_id: u64,
    gate_type: GateType,
    target_modes: [QuantumLatticeConfig.MAX_BOSONIC_MODES]u32,
    target_count: usize,
    parameters: [8]f64,
    floquet_phase: f64,
    fidelity: f64,
    execution_cycles: usize,

    const Self = @This();

    pub const GateType = enum(u8) {
        DISPLACEMENT = 0,
        SQUEEZING = 1,
        BEAM_SPLITTER = 2,
        TWO_MODE_SQUEEZING = 3,
        KERR = 4,
        CUBIC_PHASE = 5,
        QUANTUM_LATTICE_X = 6,
        QUANTUM_LATTICE_Z = 7,
        QUANTUM_LATTICE_CNOT = 8,
        FLOQUET_DRIVE = 9,
    };

    pub fn initDisplacement(mode: u32, alpha_re: f64, alpha_im: f64) Self {
        return Self{
            .gate_id = @as(u64, @truncate(@as(u128, @bitCast(std.time.nanoTimestamp())))),
            .gate_type = .DISPLACEMENT,
            .target_modes = [_]u32{0} ** QuantumLatticeConfig.MAX_BOSONIC_MODES,
            .target_count = 1,
            .parameters = [alpha_re, alpha_im, 0, 0, 0, 0, 0, 0],
            .floquet_phase = 0.0,
            .fidelity = QuantumLatticeConfig.GATE_FIDELITY_TARGET,
            .execution_cycles = 1,
        };
    }

    pub fn initBeamSplitter(mode1: u32, mode2: u32, theta: f64, phi: f64) Self {
        var gate = Self{
            .gate_id = @as(u64, @truncate(@as(u128, @bitCast(std.time.nanoTimestamp())))),
            .gate_type = .BEAM_SPLITTER,
            .target_modes = [_]u32{0} ** QuantumLatticeConfig.MAX_BOSONIC_MODES,
            .target_count = 2,
            .parameters = [theta, phi, 0, 0, 0, 0, 0, 0],
            .floquet_phase = 0.0,
            .fidelity = QuantumLatticeConfig.GATE_FIDELITY_TARGET,
            .execution_cycles = 1,
        };
        gate.target_modes[0] = mode1;
        gate.target_modes[1] = mode2;
        return gate;
    }

    pub fn initQuantumLatticeX(mode: u32, lattice_vector: [2]f64) Self {
        return Self{
            .gate_id = @as(u64, @truncate(@as(u128, @bitCast(std.time.nanoTimestamp())))),
            .gate_type = .QUANTUM_LATTICE_X,
            .target_modes = [_]u32{0} ** QuantumLatticeConfig.MAX_BOSONIC_MODES,
            .target_count = 1,
            .parameters = [lattice_vector[0], lattice_vector[1], 0, 0, 0, 0, 0, 0],
            .floquet_phase = 0.0,
            .fidelity = QuantumLatticeConfig.GATE_FIDELITY_TARGET,
            .execution_cycles = 1,
        };
    }

    pub fn initQuantumLatticeZ(mode: u32, lattice_vector: [2]f64) Self {
        return Self{
            .gate_id = @as(u64, @truncate(@as(u128, @bitCast(std.time.nanoTimestamp())))),
            .gate_type = .QUANTUM_LATTICE_Z,
            .target_modes = [_]u32{0} ** QuantumLatticeConfig.MAX_BOSONIC_MODES,
            .target_count = 1,
            .parameters = [lattice_vector[0], lattice_vector[1], 0, 0, 0, 0, 0, 0],
            .floquet_phase = 0.0,
            .fidelity = QuantumLatticeConfig.GATE_FIDELITY_TARGET,
            .execution_cycles = 1,
        };
    }

    pub fn initQuantumLatticeCNOT(control: u32, target: u32, lattice_vector: [2]f64) Self {
        var gate = Self{
            .gate_id = @as(u64, @truncate(@as(u128, @bitCast(std.time.nanoTimestamp())))),
            .gate_type = .QUANTUM_LATTICE_CNOT,
            .target_modes = [_]u32{0} ** QuantumLatticeConfig.MAX_BOSONIC_MODES,
            .target_count = 2,
            .parameters = [lattice_vector[0], lattice_vector[1], 0, 0, 0, 0, 0, 0],
            .floquet_phase = 0.0,
            .fidelity = QuantumLatticeConfig.GATE_FIDELITY_TARGET,
            .execution_cycles = 1,
        };
        gate.target_modes[0] = control;
        gate.target_modes[1] = target;
        return gate;
    }

    pub fn initFloquetDrive(mode: u32, amplitude: f64, frequency: f64, phase: f64) Self {
        return Self{
            .gate_id = @as(u64, @truncate(@as(u128, @bitCast(std.time.nanoTimestamp())))),
            .gate_type = .FLOQUET_DRIVE,
            .target_modes = [_]u32{0} ** QuantumLatticeConfig.MAX_BOSONIC_MODES,
            .target_count = 1,
            .parameters = [amplitude, frequency, phase, 0, 0, 0, 0, 0],
            .floquet_phase = phase,
            .fidelity = QuantumLatticeConfig.GATE_FIDELITY_TARGET,
            .execution_cycles = QuantumLatticeConfig.FLOQUET_PERIODS,
        };
    }
};

pub const QuantumLatticeCircuit = struct {
    gates: ArrayList(QuantumLatticeGate),
    mode_count: usize,
    depth: usize,
    total_fidelity: f64,
    error_correction_enabled: bool,
    allocator: Allocator,

    const Self = @This();

    pub fn init(allocator: Allocator, mode_count: usize) Self {
        return Self{
            .gates = ArrayList(QuantumLatticeGate).init(allocator),
            .mode_count = mode_count,
            .depth = 0,
            .total_fidelity = 1.0,
            .error_correction_enabled = true,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Self) void {
        self.gates.deinit();
    }

    pub fn appendGate(self: *Self, gate: QuantumLatticeGate) !void {
        try self.gates.append(gate);
        self.total_fidelity *= gate.fidelity;
        self.depth += 1;
    }

    pub fn appendGates(self: *Self, gates: []const QuantumLatticeGate) !void {
        for (gates) |gate| {
            try self.appendGate(gate);
        }
    }
};

pub const BosonicCode = struct {
    code_id: u64,
    logical_qubit_count: usize,
    physical_mode_count: usize,
    stabilizers: ArrayList([QuantumLatticeConfig.MAX_BOSONIC_MODES]Complex),
    logical_operators: ArrayList([QuantumLatticeConfig.MAX_BOSONIC_MODES]Complex),
    syndrome_extraction_circuit: QuantumLatticeCircuit,
    correction_circuit: QuantumLatticeCircuit,
    encoding_circuit: QuantumLatticeCircuit,
    decoding_circuit: QuantumLatticeCircuit,
    distance: usize,
    allocator: Allocator,

    const Self = @This();

    pub fn initGKP(allocator: Allocator, mode_count: usize, sqrt_pi: f64) !Self {
        var code = Self{
            .code_id = @as(u64, @truncate(@as(u128, @bitCast(std.time.nanoTimestamp())))),
            .logical_qubit_count = mode_count / 2,
            .physical_mode_count = mode_count,
            .stabilizers = ArrayList([QuantumLatticeConfig.MAX_BOSONIC_MODES]Complex).init(allocator),
            .logical_operators = ArrayList([QuantumLatticeConfig.MAX_BOSONIC_MODES]Complex).init(allocator),
            .syndrome_extraction_circuit = QuantumLatticeCircuit.init(allocator, mode_count),
            .correction_circuit = QuantumLatticeCircuit.init(allocator, mode_count),
            .encoding_circuit = QuantumLatticeCircuit.init(allocator, mode_count),
            .decoding_circuit = QuantumLatticeCircuit.init(allocator, mode_count),
            .distance = 3,
            .allocator = allocator,
        };

        for (0..mode_count) |i| {
            var stabilizer: [QuantumLatticeConfig.MAX_BOSONIC_MODES]Complex = undefined;
            var logical_op: [QuantumLatticeConfig.MAX_BOSONIC_MODES]Complex = undefined;
            for (0..QuantumLatticeConfig.MAX_BOSONIC_MODES) |j| {
                stabilizer[j] = Complex{.re = 0.0, .im = 0.0};
                logical_op[j] = Complex{.re = 0.0, .im = 0.0};
            }
            if (i < mode_count) {
                stabilizer[i] = Complex{.re = 2.0 * sqrt_pi, .im = 0.0};
                logical_op[i] = Complex{.re = sqrt_pi, .im = 0.0};
            }
            try code.stabilizers.append(stabilizer);
            try code.logical_operators.append(logical_op);
        }

        try code.buildGKPCircuits(sqrt_pi);
        return code;
    }

    fn buildGKPCircuits(self: *Self, sqrt_pi: f64) !void {
        for (0..self.physical_mode_count) |i| {
            try self.encoding_circuit.appendGate(QuantumLatticeGate.initDisplacement(@intCast(u32, i), sqrt_pi, 0.0));
            try self.encoding_circuit.appendGate(QuantumLatticeGate.initQuantumLatticeX(@intCast(u32, i), .{sqrt_pi, 0.0}));
            try self.encoding_circuit.appendGate(QuantumLatticeGate.initQuantumLatticeZ(@intCast(u32, i), .{0.0, sqrt_pi}));
        }

        for (0..self.physical_mode_count) |i| {
            try self.syndrome_extraction_circuit.appendGate(QuantumLatticeGate.initQuantumLatticeX(@intCast(u32, i), .{2.0 * sqrt_pi, 0.0}));
            try self.syndrome_extraction_circuit.appendGate(QuantumLatticeGate.initQuantumLatticeZ(@intCast(u32, i), .{0.0, 2.0 * sqrt_pi}));
        }

        for (0..self.physical_mode_count) |i| {
            try self.correction_circuit.appendGate(QuantumLatticeGate.initDisplacement(@intCast(u32, i), -sqrt_pi, 0.0));
            try self.correction_circuit.appendGate(QuantumLatticeGate.initDisplacement(@intCast(u32, i), 0.0, -sqrt_pi));
        }

        for (0..self.physical_mode_count) |i| {
            try self.decoding_circuit.appendGate(QuantumLatticeGate.initQuantumLatticeX(@intCast(u32, i), .{sqrt_pi, 0.0}));
            try self.decoding_circuit.appendGate(QuantumLatticeGate.initQuantumLatticeZ(@intCast(u32, i), .{0.0, sqrt_pi}));
        }
    }

    pub fn deinit(self: *Self) void {
        self.stabilizers.deinit();
        self.logical_operators.deinit();
        self.syndrome_extraction_circuit.deinit();
        self.correction_circuit.deinit();
        self.encoding_circuit.deinit();
        self.decoding_circuit.deinit();
    }
};

pub const SinglePeriodFloquetController = struct {
    drive_amplitude: f64,
    drive_frequency: f64,
    drive_phase: f64,
    lattice_vectors: [QuantumLatticeConfig.LATTICE_DEPTH][2]f64,
    target_gates: [QuantumLatticeConfig.LATTICE_DEPTH]QuantumLatticeGate.GateType,
    period_ns: u64,
    cycles_completed: u64,
    coherence_preserved: bool,

    const Self = @This();

    pub fn init(amplitude: f64, frequency: f64, phase: f64, lattice_vectors: [QuantumLatticeConfig.LATTICE_DEPTH][2]f64, target_gates: [QuantumLatticeConfig.LATTICE_DEPTH]QuantumLatticeGate.GateType) Self {
        return Self{
            .drive_amplitude = amplitude,
            .drive_frequency = frequency,
            .drive_phase = phase,
            .lattice_vectors = lattice_vectors,
            .target_gates = target_gates,
            .period_ns = @as(u64, @intCast(1_000_000_000.0 / frequency)),
            .cycles_completed = 0,
            .coherence_preserved = true,
        };
    }

    pub fn generateFloquetSequence(self: *Self, mode: u32) [QuantumLatticeConfig.LATTICE_DEPTH]QuantumLatticeGate {
        var sequence: [QuantumLatticeConfig.LATTICE_DEPTH]QuantumLatticeGate = undefined;
        for (0..QuantumLatticeConfig.LATTICE_DEPTH) |i| {
            switch (self.target_gates[i]) {
                .QUANTUM_LATTICE_X => {
                    sequence[i] = QuantumLatticeGate.initQuantumLatticeX(mode, self.lattice_vectors[i]);
                },
                .QUANTUM_LATTICE_Z => {
                    sequence[i] = QuantumLatticeGate.initQuantumLatticeZ(mode, self.lattice_vectors[i]);
                },
                .QUANTUM_LATTICE_CNOT => {
                    sequence[i] = QuantumLatticeGate.initQuantumLatticeCNOT(mode, (mode + 1) % QuantumLatticeConfig.MAX_BOSONIC_MODES, self.lattice_vectors[i]);
                },
                .FLOQUET_DRIVE => {
                    sequence[i] = QuantumLatticeGate.initFloquetDrive(mode, self.drive_amplitude, self.drive_frequency, self.drive_phase + @as(f64, @floatFromInt(i)) * 2.0 * math.pi / @as(f64, @floatFromInt(QuantumLatticeConfig.LATTICE_DEPTH)));
                },
                else => {
                    sequence[i] = QuantumLatticeGate.initDisplacement(mode, 0.0, 0.0);
                },
            }
        }
        return sequence;
    }

    pub fn executeSinglePeriod(self: *Self, modes: *[QuantumLatticeConfig.MAX_BOSONIC_MODES]BosonicMode, active_modes: usize) !void {
        for (0..active_modes) |mode_idx| {
            const sequence = self.generateFloquetSequence(@intCast(u32, mode_idx));
            for (0..QuantumLatticeConfig.LATTICE_DEPTH) |depth_idx| {
                try self.applyGate(&modes[mode_idx], sequence[depth_idx]);
            }
        }
        self.cycles_completed += 1;
        self.coherence_preserved = self.cycles_completed * self.period_ns < QuantumLatticeConfig.COHERENCE_TIME_NS;
    }

    fn applyGate(self: *Self, mode: *BosonicMode, gate: QuantumLatticeGate) !void {
        switch (gate.gate_type) {
            .DISPLACEMENT => {
                mode.applyDisplacement(Complex{.re = gate.parameters[0], .im = gate.parameters[1]});
            },
            .SQUEEZING => {
                mode.applySqueezing(Complex{.re = gate.parameters[0], .im = gate.parameters[1]});
            },
            .QUANTUM_LATTICE_X => {
                const dx = gate.parameters[0];
                mode.applyDisplacement(Complex{.re = dx, .im = 0.0});
                mode.error_syndrome[0] ^= 1;
            },
            .QUANTUM_LATTICE_Z => {
                const dp = gate.parameters[1];
                mode.applyDisplacement(Complex{.re = 0.0, .im = dp});
                mode.error_syndrome[1] ^= 1;
            },
            .QUANTUM_LATTICE_CNOT => {
                mode.error_syndrome[2] ^= 1;
            },
            .FLOQUET_DRIVE => {
                const amp = gate.parameters[0];
                const freq = gate.parameters[1];
                const phase = gate.parameters[2];
                const t = @as(f64, @floatFromInt(self.cycles_completed)) * @as(f64, @floatFromInt(self.period_ns)) / 1e9;
                const displacement = amp * @cos(2.0 * math.pi * freq * t + phase);
                mode.applyDisplacement(Complex{.re = displacement, .im = 0.0});
            },
            else => {},
        }
    }
};

pub const QuantumAdvantageVerifier = struct {
    problem_size: usize,
    quantum_depth: usize,
    classical_width_lower_bound: f64,
    separation_proven: bool,
    advantage_factor: f64,

    const Self = @This();

    pub const ProblemType = enum(u8) {
        ITERATED_INDEX = 0,
        PARITY_SAMPLING = 1,
        RECURSIVE_FOURIER = 2,
        BOSONIC_SAMPLING = 3,
    };

    pub fn initIteratedIndex(n: usize) Self {
        return Self{
            .problem_size = n,
            .quantum_depth = @max(1, @intCast(usize, @ceil(@log2(@log2(@as(f64, @floatFromInt(n))))))) + 1,
            .classical_width_lower_bound = @pow(@as(f64, @floatFromInt(n)), 0.5),
            .separation_proven = true,
            .advantage_factor = @as(f64, @floatFromInt(n)) / @as(f64, @floatFromInt(@max(1, @intCast(usize, @ceil(@log2(@log2(@as(f64, @floatFromInt(n))))))))),
        };
    }

    pub fn initParitySampling(n: usize) Self {
        return Self{
            .problem_size = n,
            .quantum_depth = 2,
            .classical_width_lower_bound = @pow(@as(f64, @floatFromInt(n)), 0.5),
            .separation_proven = true,
            .advantage_factor = @as(f64, @floatFromInt(n)) / 4.0,
        };
    }

    pub fn verifyAdvantage(self: *Self, problem_type: ProblemType) bool {
        switch (problem_type) {
            .ITERATED_INDEX => {
                return self.separation_proven and self.quantum_depth <= 10 and self.classical_width_lower_bound > @as(f64, @floatFromInt(self.problem_size));
            },
            .PARITY_SAMPLING => {
                return self.separation_proven and self.quantum_depth <= 5;
            },
            .RECURSIVE_FOURIER => {
                return self.quantum_depth <= 3 and self.classical_width_lower_bound > 1000.0;
            },
            .BOSONIC_SAMPLING => {
                return self.quantum_depth <= 1 and self.advantage_factor > 1000.0;
            },
        }
    }
};

pub const QuantumLatticeJaideCore = struct {
    modes: [QuantumLatticeConfig.MAX_BOSONIC_MODES]BosonicMode,
    active_mode_count: usize,
    bosonic_code: BosonicCode,
    floquet_controller: SinglePeriodFloquetController,
    advantage_verifier: QuantumAdvantageVerifier,
    reasoning_graph: *ReasoningGraph,
    allocator: Allocator,
    total_operations: u64,
    error_correction_cycles: u64,
    quantum_advantage_achieved: bool,

    const Self = @This();

    pub const ReasoningGraph = struct {
        nodes: AutoHashMap(u64, ReasoningNode, std.hash_map.DefaultHashContext(u64), Allocator),
        edges: AutoHashMap(u64, ReasoningEdge, std.hash_map.DefaultHashContext(u64), Allocator),
        quantum_layers: [QuantumLatticeConfig.LATTICE_DEPTH]AutoHashMap(u64, QuantumLayerState, std.hash_map.DefaultHashContext(u64), Allocator),
        allocator: Allocator,

        const Self = @This();

        pub const ReasoningNode = struct {
            id: u64,
            mode_indices: [8]u32,
            mode_count: usize,
            state_vector: [QuantumLatticeConfig.MAX_BOSONIC_MODES]Complex,
            energy: f64,
            convergence_metric: f64,
        };

        pub const ReasoningEdge = struct {
            id: u64,
            source: u64,
            target: u64,
            weight: f64,
            quantum_correlation: Complex,
            fractal_dimension: f64,
            lattice_gate_sequence: ArrayList(QuantumLatticeGate),
        };

        pub const QuantumLayerState = struct {
            layer_id: usize,
            active_gates: ArrayList(QuantumLatticeGate),
            fidelity: f64,
            error_syndromes: ArrayList([4]u8),
        };

        pub fn init(allocator: Allocator) Self {
            var quantum_layers: [QuantumLatticeConfig.LATTICE_DEPTH]AutoHashMap(u64, QuantumLayerState, std.hash_map.DefaultHashContext(u64), Allocator) = undefined;
            for (0..QuantumLatticeConfig.LATTICE_DEPTH) |i| {
                quantum_layers[i] = AutoHashMap(u64, QuantumLayerState).init(allocator);
            }
            return Self{
                .nodes = AutoHashMap(u64, ReasoningNode).init(allocator),
                .edges = AutoHashMap(u64, ReasoningEdge).init(allocator),
                .quantum_layers = quantum_layers,
                .allocator = allocator,
            };
        }

        pub fn deinit(self: *Self) void {
            var node_iter = self.nodes.iterator();
            while (node_iter.next()) |entry| {
                entry.value_ptr.*.deinit();
            }
            self.nodes.deinit();

            var edge_iter = self.edges.iterator();
            while (edge_iter.next()) |entry| {
                entry.value_ptr.*.lattice_gate_sequence.deinit();
            }
            self.edges.deinit();

            for (0..QuantumLatticeConfig.LATTICE_DEPTH) |i| {
                var layer_iter = self.quantum_layers[i].iterator();
                while (layer_iter.next()) |entry| {
                    entry.value_ptr.*.active_gates.deinit();
                    entry.value_ptr.*.error_syndromes.deinit();
                }
                self.quantum_layers[i].deinit();
            }
        }
    };

    pub fn init(allocator: Allocator, mode_count: usize) !Self {
        const sqrt_pi = @sqrt(math.pi);

        var modes: [QuantumLatticeConfig.MAX_BOSONIC_MODES]BosonicMode = undefined;
        for (0..QuantumLatticeConfig.MAX_BOSONIC_MODES) |i| {
            if (i < mode_count) {
                modes[i] = try BosonicMode.init(allocator, @intCast(u32, i));
            } else {
                modes[i] = BosonicMode{
                    .id = @intCast(u32, i),
                    .displacement = Complex{.re = 0.0, .im = 0.0},
                    .squeezing = Complex{.re = 1.0, .im = 0.0},
                    .photon_number = 0.0,
                    .coherence_time_ns = QuantumLatticeConfig.COHERENCE_TIME_NS,
                    .error_syndrome = [_]u8{0, 0, 0, 0},
                    .entanglement_map = AutoHashMap(u32, f64).init(allocator),
                };
            }
        }

        var lattice_vectors: [QuantumLatticeConfig.LATTICE_DEPTH][2]f64 = undefined;
        var target_gates: [QuantumLatticeConfig.LATTICE_DEPTH]QuantumLatticeGate.GateType = undefined;
        for (0..QuantumLatticeConfig.LATTICE_DEPTH) |i| {
            const angle = @as(f64, @floatFromInt(i)) * 2.0 * math.pi / @as(f64, @floatFromInt(QuantumLatticeConfig.LATTICE_DEPTH));
            lattice_vectors[i] = .{sqrt_pi * @cos(angle), sqrt_pi * @sin(angle)};
            target_gates[i] = if (i % 3 == 0) .QUANTUM_LATTICE_X else if (i % 3 == 1) .QUANTUM_LATTICE_Z else .QUANTUM_LATTICE_CNOT;
        }

        var core = Self{
            .modes = modes,
            .active_mode_count = mode_count,
            .bosonic_code = try BosonicCode.initGKP(allocator, mode_count, sqrt_pi),
            .floquet_controller = SinglePeriodFloquetController.init(0.1, 5e9, 0.0, lattice_vectors, target_gates),
            .advantage_verifier = QuantumAdvantageVerifier.initIteratedIndex(mode_count * 10),
            .reasoning_graph = try allocator.create(ReasoningGraph.init(allocator)),
            .allocator = allocator,
            .total_operations = 0,
            .error_correction_cycles = 0,
            .quantum_advantage_achieved = false,
        };

        try core.initializeReasoningGraph();
        return core;
    }

    fn initializeReasoningGraph(self: *Self) !void {
        const graph = self.reasoning_graph.*;
        for (0..self.active_mode_count) |i| {
            var node = ReasoningGraph.ReasoningNode{
                .id = @as(u64, @intCast(i)),
                .mode_indices = [_]u32{0} ** 8,
                .mode_count = 1,
                .state_vector = [_]Complex{0} ** QuantumLatticeConfig.MAX_BOSONIC_MODES,
                .energy = 1.0,
                .convergence_metric = 1.0,
            };
            node.mode_indices[0] = @intCast(u32, i);
            node.state_vector[i] = Complex{.re = 1.0, .im = 0.0};
            try graph.nodes.put(node.id, node);
        }

        for (0..self.active_mode_count - 1) |i| {
            var edge = ReasoningGraph.ReasoningEdge{
                .id = @as(u64, @intCast(i + 1000)),
                .source = @as(u64, @intCast(i)),
                .target = @as(u64, @intCast(i + 1)),
                .weight = 1.0,
                .quantum_correlation = Complex{.re = 1.0, .im = 0.0},
                .fractal_dimension = 2.0,
                .lattice_gate_sequence = ArrayList(QuantumLatticeGate).init(self.allocator),
            };
            try edge.lattice_gate_sequence.append(QuantumLatticeGate.initBeamSplitter(@intCast(u32, i), @intCast(u32, i + 1), math.pi / 4.0, 0.0));
            try edge.lattice_gate_sequence.append(QuantumLatticeGate.initQuantumLatticeCNOT(@intCast(u32, i), @intCast(u32, i + 1), .{math.pi, 0.0}));
            try graph.edges.put(edge.id, edge);
        }
    }

    pub fn deinit(self: *Self) void {
        for (0..QuantumLatticeConfig.MAX_BOSONIC_MODES) |i| {
            if (i < self.active_mode_count) {
                self.modes[i].deinit();
            }
        }
        self.bosonic_code.deinit();
        self.reasoning_graph.*.deinit();
        self.allocator.destroy(self.reasoning_graph);
    }

    pub fn executeQuantumReasoningCycle(self: *Self) !f64 {
        try self.floquet_controller.executeSinglePeriod(&self.modes, self.active_mode_count);
        self.total_operations += QuantumLatticeConfig.LATTICE_DEPTH * self.active_mode_count;

        try self.performErrorCorrection();
        self.error_correction_cycles += 1;

        const energy = self.computeGraphEnergy();

        try self.updateReasoningGraph(energy);

        if (self.error_correction_cycles % 10 == 0) {
            self.quantum_advantage_achieved = self.advantage_verifier.verifyAdvantage(.BOSONIC_SAMPLING);
        }

        return energy;
    }

    fn performErrorCorrection(self: *Self) !void {
        for (0..self.active_mode_count) |i| {
            const mode = &self.modes[i];
            if (mode.error_syndrome[0] != 0 || mode.error_syndrome[1] != 0) {
                for (self.bosonic_code.correction_circuit.gates.items) |gate| {
                    if (gate.target_modes[0] == @intCast(u32, i)) {
                        self.applyGateToMode(i, gate);
                    }
                }
                self.modes[i].error_syndrome = [_]u8{0, 0, 0, 0};
            }
        }
    }

    fn applyGateToMode(self: *Self, mode_idx: usize, gate: QuantumLatticeGate) void {
        const mode = &self.modes[mode_idx];
        switch (gate.gate_type) {
            .DISPLACEMENT => {
                mode.applyDisplacement(Complex{.re = gate.parameters[0], .im = gate.parameters[1]});
            },
            .SQUEEZING => {
                mode.applySqueezing(Complex{.re = gate.parameters[0], .im = gate.parameters[1]});
            },
            .QUANTUM_LATTICE_X => {
                mode.applyDisplacement(Complex{.re = gate.parameters[0], .im = 0.0});
            },
            .QUANTUM_LATTICE_Z => {
                mode.applyDisplacement(Complex{.re = 0.0, .im = gate.parameters[1]});
            },
            else => {},
        }
    }

    fn computeGraphEnergy(self: *Self) f64 {
        var total_energy: f64 = 0.0;
        var count: usize = 0;

        var node_iter = self.reasoning_graph.*.nodes.iterator();
        while (node_iter.next()) |entry| {
            const node = entry.value_ptr;
            var node_energy: f64 = 0.0;
            for (0..node.mode_count) |i| {
                const mode_idx = node.mode_indices[i];
                if (mode_idx < self.active_mode_count) {
                    const mode = &self.modes[mode_idx];
                    node_energy += mode.photon_number * mode.squeezing.re;
                }
            }
            node.energy = node_energy / @as(f64, @floatFromInt(@max(1, node.mode_count)));
            total_energy += node.energy;
            count += 1;
        }

        var edge_iter = self.reasoning_graph.*.edges.iterator();
        while (edge_iter.next()) |entry| {
            const edge = entry.value_ptr;
            total_energy += edge.weight * edge.fractal_dimension;
            total_energy += edge.quantum_correlation.magnitude();
            count += 1;
        }

        if (count > 0) {
            return total_energy / @as(f64, @floatFromInt(count));
        }
        return 1e6;
    }

    fn updateReasoningGraph(self: *Self, energy: f64) !void {
        var node_iter = self.reasoning_graph.*.nodes.iterator();
        while (node_iter.next()) |entry| {
            const node = entry.value_ptr;
            node.convergence_metric = @abs(node.energy - energy);
            for (0..node.mode_count) |i| {
                const mode_idx = node.mode_indices[i];
                if (mode_idx < self.active_mode_count) {
                    node.state_vector[mode_idx] = Complex{.re = self.modes[mode_idx].displacement.re, .im = self.modes[mode_idx].displacement.im};
                }
            }
        }

        var edge_iter = self.reasoning_graph.*.edges.iterator();
        while (edge_iter.next()) |entry| {
            const edge = entry.value_ptr;
            const source_mode = &self.modes[@intCast(usize, edge.source)];
            const target_mode = &self.modes[@intCast(usize, edge.target)];
            edge.quantum_correlation.re = source_mode.displacement.re * target_mode.displacement.re - source_mode.displacement.im * target_mode.displacement.im;
            edge.quantum_correlation.im = source_mode.displacement.re * target_mode.displacement.im + source_mode.displacement.im * target_mode.displacement.re;
            edge.fractal_dimension = 1.0 + @log(1.0 + edge.quantum_correlation.magnitude());
        }
    }

    pub fn runQuantumAdvantageBenchmark(self: *Self, cycles: usize) !BenchmarkResult {
        var best_energy: f64 = std.math.inf(f64);
        var start_time = std.time.nanoTimestamp();

        for (0..cycles) |i| {
            const energy = try self.executeQuantumReasoningCycle();
            if (energy < best_energy) {
                best_energy = energy;
            }
            if (energy < QuantumLatticeConfig.ERROR_THRESHOLD) {
                break;
            }
        }

        var end_time = std.time.nanoTimestamp();

        return BenchmarkResult{
            .cycles_completed = cycles,
            .best_energy = best_energy,
            .total_time_ns = end_time - start_time,
            .total_operations = self.total_operations,
            .error_correction_cycles = self.error_correction_cycles,
            .quantum_advantage_achieved = self.quantum_advantage_achieved,
            .average_fidelity = self.bosonic_code.encoding_circuit.total_fidelity,
            .operations_per_ns = @as(f64, @floatFromInt(self.total_operations)) / @as(f64, @floatFromInt(end_time - start_time)),
            .theoretical_advantage_factor = self.advantage_verifier.advantage_factor,
        };
    }

    pub const BenchmarkResult = struct {
        cycles_completed: usize,
        best_energy: f64,
        total_time_ns: u64,
        total_operations: u64,
        error_correction_cycles: u64,
        quantum_advantage_achieved: bool,
        average_fidelity: f64,
        operations_per_ns: f64,
        theoretical_advantage_factor: f64,
    };
};

