pub const QuantumLatticeConfig = struct {
    pub const MAX_BOSONIC_MODES: usize = 64;
    pub const LATTICE_DEPTH: usize = 8;
    pub const FLOQUET_PERIODS: usize = 1;
    pub const CONVERGENCE_THRESHOLD: f64 = 1.0e-9;
    pub const COHERENCE_TIME_NS: u64 = 1_000_000;
    pub const GATE_FIDELITY_TARGET: f64 = 0.999999;
    pub const CNOT_COUPLING: f64 = 0.5;
    pub const KERR_NONLINEARITY: f64 = 0.01;
    pub const CUBIC_PHASE_GAIN: f64 = 0.001;
};

fn coshF(x: f64) f64 {
    return (@exp(x) + @exp(-x)) * 0.5;
}

fn sinhF(x: f64) f64 {
    return (@exp(x) - @exp(-x)) * 0.5;
}

pub const BosonicMode = struct {
    id: u32,
    displacement: C64,
    squeezing: C64,
    photon_number: f64,
    coherence_time_ns: u64,
    syndrome: [4]u8,
    x_correction_total: f64,
    p_correction_total: f64,
    correlations: AutoHashMap(u32, f64),

    const Self = @This();

    pub fn init(allocator: Allocator, id: u32) Self {
        return Self{
            .id = id,
            .displacement = C64.init(0.0, 0.0),
            .squeezing = C64.init(1.0, 0.0),
            .photon_number = 0.0,
            .coherence_time_ns = QuantumLatticeConfig.COHERENCE_TIME_NS,
            .syndrome = [_]u8{0} ** 4,
            .x_correction_total = 0.0,
            .p_correction_total = 0.0,
            .correlations = AutoHashMap(u32, f64).init(allocator),
        };
    }

    pub fn deinit(self: *Self) void {
        self.correlations.deinit();
    }

    pub fn setDisplacement(self: *Self, next: C64) void {
        self.displacement = next;
        const m = self.displacement.magnitude();
        self.photon_number = m * m;
    }

    pub fn displace(self: *Self, alpha: C64) void {
        self.setDisplacement(self.displacement.add(alpha));
    }

    pub fn squeeze(self: *Self, zeta: C64) void {
        const r = zeta.magnitude();
        if (r == 0.0) return;
        const ch = coshF(r);
        const sh = sinhF(r);
        self.squeezing = C64.init(ch, sh);
        const m = self.displacement.magnitude();
        self.photon_number = m * m * ch;
    }

    pub fn resetSyndrome(self: *Self) void {
        self.syndrome = [_]u8{0} ** 4;
    }

    pub fn anySyndrome(self: *const Self) bool {
        return self.syndrome[0] != 0 or self.syndrome[1] != 0 or self.syndrome[2] != 0 or self.syndrome[3] != 0;
    }
};

pub const GateKind = enum(u8) {
