        self.total_fidelity *= gate.fidelity;
    }
};

pub fn applyGate(modes: []BosonicMode, gate: QuantumLatticeGate, time_seconds: f64) void {
    if (gate.target_count == 0) return;
    const t0: usize = @intCast(gate.targets[0]);
    if (t0 >= modes.len) return;
    switch (gate.kind) {
        .displacement => {
            modes[t0].displace(C64.init(gate.params[0], gate.params[1]));
        },
        .squeezing => {
            modes[t0].squeeze(C64.init(gate.params[0], 0.0));
        },
        .beam_splitter => {
            const t1: usize = @intCast(gate.targets[1]);
            if (t1 >= modes.len or t1 == t0) return;
            const theta = gate.params[0];
            const phi = gate.params[1];
            const c = C64.init(@cos(theta), 0.0);
            const e = C64.init(@sin(theta) * @cos(phi), @sin(theta) * @sin(phi));
            const ec = C64.init(@sin(theta) * @cos(phi), -@sin(theta) * @sin(phi));
            const a = modes[t0].displacement;
            const b = modes[t1].displacement;
            const next_a = a.mul(c).add(e.mul(b));
            const next_b = b.mul(c).sub(ec.mul(a));
            modes[t0].setDisplacement(next_a);
            modes[t1].setDisplacement(next_b);
        },
        .two_mode_squeezing => {
            const t1: usize = @intCast(gate.targets[1]);
            if (t1 >= modes.len or t1 == t0) return;
            const f = sinhF(gate.params[0]);
            const a = modes[t0].displacement;
            const b = modes[t1].displacement;
            const da = C64.init(f * b.re, -f * b.im);
            const db = C64.init(f * a.re, -f * a.im);
            modes[t0].displace(da);
            modes[t1].displace(db);
        },
        .kerr => {
            const chi = gate.params[0];
            const phase = chi * modes[t0].photon_number;
            const rot = C64.init(@cos(phase), @sin(phase));
            const next = modes[t0].displacement.mul(rot);
            modes[t0].setDisplacement(next);
        },
        .cubic_phase => {
            const gain = gate.params[0];
            const d = modes[t0].displacement;
            const next = C64.init(d.re, d.im - gain * d.re * d.re);
            modes[t0].setDisplacement(next);
        },
        .lattice_x => {
            modes[t0].displace(C64.init(gate.params[0], 0.0));
            modes[t0].syndrome[0] ^= 1;
            modes[t0].x_correction_total += gate.params[0];
        },
        .lattice_z => {
            modes[t0].displace(C64.init(0.0, gate.params[1]));
            modes[t0].syndrome[1] ^= 1;
            modes[t0].p_correction_total += gate.params[1];
        },
        .lattice_cnot => {
            const t1: usize = @intCast(gate.targets[1]);
            if (t1 >= modes.len or t1 == t0) return;
            const coupling = gate.params[0];
            const control_quadrature = modes[t0].displacement.re;
            modes[t1].displace(C64.init(control_quadrature * coupling, 0.0));
            modes[t0].syndrome[2] ^= 1;
            modes[t1].syndrome[3] ^= 1;
        },
        .floquet_drive => {
            const amplitude = gate.params[0];
            const frequency = gate.params[1];
            const phase = gate.params[2];
            const dx = amplitude * @cos(2.0 * math.pi * frequency * time_seconds + phase);
            modes[t0].displace(C64.init(dx, 0.0));
        },
    }
}

pub const GKPCode = struct {
    sqrt_pi: f64,
    physical_mode_count: usize,
    logical_qubit_count: usize,
    distance: usize,
    encode: LatticeCircuit,
    syndrome_extract: LatticeCircuit,
    correct: LatticeCircuit,
    decode: LatticeCircuit,

    const Self = @This();

    pub fn init(allocator: Allocator, mode_count: usize) !Self {
        const sp = @sqrt(math.pi);
        var code = Self{
            .sqrt_pi = sp,
            .physical_mode_count = mode_count,
            .logical_qubit_count = mode_count / 2,
            .distance = 3,
            .encode = LatticeCircuit.init(allocator),
            .syndrome_extract = LatticeCircuit.init(allocator),
            .correct = LatticeCircuit.init(allocator),
            .decode = LatticeCircuit.init(allocator),
        };
        var serial: u64 = 1000;
        for (0..mode_count) |i| {
            const m: u32 = @intCast(i);
            try code.encode.appendGate(QuantumLatticeGate.displacement(serial, m, sp, 0.0));
            serial += 1;
            try code.encode.appendGate(QuantumLatticeGate.latticeX(serial, m, sp));
            serial += 1;
            try code.encode.appendGate(QuantumLatticeGate.latticeZ(serial, m, sp));
            serial += 1;
            try code.syndrome_extract.appendGate(QuantumLatticeGate.latticeX(serial, m, 2.0 * sp));
            serial += 1;
            try code.syndrome_extract.appendGate(QuantumLatticeGate.latticeZ(serial, m, 2.0 * sp));
            serial += 1;
            try code.correct.appendGate(QuantumLatticeGate.displacement(serial, m, -sp, 0.0));
            serial += 1;
            try code.correct.appendGate(QuantumLatticeGate.displacement(serial, m, 0.0, -sp));
            serial += 1;
            try code.decode.appendGate(QuantumLatticeGate.latticeX(serial, m, sp));
            serial += 1;
            try code.decode.appendGate(QuantumLatticeGate.latticeZ(serial, m, sp));
            serial += 1;
        }
        return code;
    }

    pub fn deinit(self: *Self) void {
        self.encode.deinit();
        self.syndrome_extract.deinit();
        self.correct.deinit();
        self.decode.deinit();
    }
};

pub const FloquetController = struct {
    amplitude: f64,
    frequency: f64,
    phase: f64,
    vectors: [QuantumLatticeConfig.LATTICE_DEPTH][2]f64,
    kinds: [QuantumLatticeConfig.LATTICE_DEPTH]GateKind,
    period_ns: u64,
    cycles_completed: u64,
    serial_base: u64,
    active_modes: usize,
    coherence_preserved: bool,

    const Self = @This();

    pub fn init(amplitude: f64, frequency: f64, phase: f64, vectors: [QuantumLatticeConfig.LATTICE_DEPTH][2]f64, kinds: [QuantumLatticeConfig.LATTICE_DEPTH]GateKind) Self {
        const raw_period: u64 = if (frequency > 0.0) @intFromFloat(1.0e9 / frequency) else 1;
        return Self{
            .amplitude = amplitude,
            .frequency = frequency,
            .phase = phase,
            .vectors = vectors,
            .kinds = kinds,
            .period_ns = @max(@as(u64, 1), raw_period),
            .cycles_completed = 0,
            .serial_base = 1_000_000,
            .active_modes = 0,
            .coherence_preserved = true,
        };
    }

    fn buildGate(self: *Self, depth_index: usize, mode: u32) QuantumLatticeGate {
        const serial = self.serial_base + @as(u64, @intCast(self.cycles_completed * QuantumLatticeConfig.LATTICE_DEPTH + depth_index));
        const v = self.vectors[depth_index];
        const mode_cap: u32 = if (self.active_modes > 1) @intCast(self.active_modes) else 1;
        const partner: u32 = (mode + 1) % mode_cap;
        const step_phase = self.phase + @as(f64, @floatFromInt(depth_index)) * 2.0 * math.pi / @as(f64, @floatFromInt(QuantumLatticeConfig.LATTICE_DEPTH));
        return switch (self.kinds[depth_index]) {
            .lattice_x => QuantumLatticeGate.latticeX(serial, mode, v[0]),
            .lattice_z => QuantumLatticeGate.latticeZ(serial, mode, v[1]),
            .lattice_cnot => QuantumLatticeGate.latticeCnot(serial, mode, partner, QuantumLatticeConfig.CNOT_COUPLING),
            .floquet_drive => QuantumLatticeGate.floquetDrive(serial, mode, self.amplitude, self.frequency, step_phase),
            .beam_splitter => QuantumLatticeGate.beamSplitter(serial, mode, partner, math.pi / 4.0, 0.0),
            .two_mode_squeezing => QuantumLatticeGate.twoModeSqueezing(serial, mode, partner, 0.1),
            .kerr => QuantumLatticeGate.kerr(serial, mode, QuantumLatticeConfig.KERR_NONLINEARITY),
            .cubic_phase => QuantumLatticeGate.cubicPhase(serial, mode, QuantumLatticeConfig.CUBIC_PHASE_GAIN),
            else => QuantumLatticeGate.displacement(serial, mode, 0.0, 0.0),
        };
    }

    pub fn executeSinglePeriod(self: *Self, modes: []BosonicMode) void {
        self.active_modes = modes.len;
        const time_seconds = @as(f64, @floatFromInt(self.cycles_completed * @as(u64, QuantumLatticeConfig.FLOQUET_PERIODS))) * @as(f64, @floatFromInt(self.period_ns)) / 1.0e9;
        for (0..modes.len) |i| {
            const mode_id: u32 = @intCast(i);
            for (0..QuantumLatticeConfig.LATTICE_DEPTH) |d| {
                const gate = self.buildGate(d, mode_id);
                applyGate(modes, gate, time_seconds);
            }
        }
        self.cycles_completed += 1;
        const elapsed: u64 = self.cycles_completed *% self.period_ns;
        self.coherence_preserved = elapsed < QuantumLatticeConfig.COHERENCE_TIME_NS;
    }
};

pub const ProblemKind = enum(u8) {
    iterated_index = 0,
    parity_sampling = 1,
    recursive_fourier = 2,
    bosonic_sampling = 3,
};

pub const QuantumAdvantageVerifier = struct {
    problem_size: usize,
    quantum_depth: usize,
    classical_width_lower_bound: f64,
    separation_proven: bool,
    advantage_factor: f64,

    const Self = @This();

    pub fn initIteratedIndex(n: usize) Self {
        const nf = @as(f64, @floatFromInt(@max(n, 4)));
        const inner = @max(@as(f64, 2.0), @log2(nf));
        const raw_depth: usize = @intFromFloat(@ceil(@log2(inner)));
        const depth = raw_depth + 1;
        return Self{
            .problem_size = n,
            .quantum_depth = depth,
            .classical_width_lower_bound = math.pow(f64, nf, 0.5),
            .separation_proven = n >= 16,
            .advantage_factor = nf / @as(f64, @floatFromInt(depth)),
        };
    }

    pub fn initParitySampling(n: usize) Self {
        const nf = @as(f64, @floatFromInt(@max(n, 4)));
        return Self{
            .problem_size = n,
            .quantum_depth = 2,
            .classical_width_lower_bound = math.pow(f64, nf, 0.5),
            .separation_proven = n >= 4,
            .advantage_factor = nf / 4.0,
        };
    }

    pub fn verify(self: *const Self, kind: ProblemKind) bool {
        return switch (kind) {
            .iterated_index => self.separation_proven and self.quantum_depth <= 10,
            .parity_sampling => self.separation_proven and self.quantum_depth <= 5,
            .recursive_fourier => self.quantum_depth <= 3 and self.classical_width_lower_bound > 1000.0,
            .bosonic_sampling => self.quantum_depth <= 2 or self.advantage_factor > 1.0,
        };
    }
};

pub const ReasoningNode = struct {
    id: u64,
    mode_id: u32,
    energy: f64,
    convergence: f64,
};

pub const ReasoningEdge = struct {
    id: u64,
    source: u64,
    target: u64,
    weight: f64,
    correlation: C64,
    fractal_dimension: f64,
    sequence: [2]QuantumLatticeGate,
};

pub const ReasoningGraph = struct {
    nodes: AutoHashMap(u64, ReasoningNode),
    edges: AutoHashMap(u64, ReasoningEdge),
    allocator: Allocator,

    const Self = @This();

    pub fn init(allocator: Allocator) Self {
        return Self{
            .nodes = AutoHashMap(u64, ReasoningNode).init(allocator),
            .edges = AutoHashMap(u64, ReasoningEdge).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Self) void {
        self.nodes.deinit();
        self.edges.deinit();
    }

    pub fn addNode(self: *Self, node: ReasoningNode) !void {
        try self.nodes.put(node.id, node);
    }

    pub fn addEdge(self: *Self, edge: ReasoningEdge) !void {
        try self.edges.put(edge.id, edge);
    }
};

pub const BenchmarkResult = struct {
    cycles_completed: usize,
    best_energy: f64,
    total_time_ns: u64,
    total_operations: u64,
    error_correction_cycles: u64,
    quantum_advantage_reported: bool,
    mean_gate_fidelity: f64,
    operations_per_ns: f64,
    analytic_advantage_factor: f64,
    coherence_preserved: bool,
    logical_error_rate: f64,
};

pub const QuantumLatticeJaideCore = struct {
    allocator: Allocator,
    modes: ArrayList(BosonicMode),
    code: GKPCode,
    floquet: FloquetController,
    verifier: QuantumAdvantageVerifier,
    graph: ReasoningGraph,
    total_operations: u64,
    error_correction_cycles: u64,
    quantum_advantage_reported: bool,
    logical_error_rate: f64,

    const Self = @This();

    pub fn init(allocator: Allocator, mode_count: usize) !Self {
        if (mode_count < 2 or mode_count > QuantumLatticeConfig.MAX_BOSONIC_MODES) {
            return error.InvalidModeCount;
        }

        var modes = ArrayList(BosonicMode).init(allocator);
        errdefer {
            for (modes.items) |*m| m.deinit();
            modes.deinit();
        }
        for (0..mode_count) |i| {
            try modes.append(BosonicMode.init(allocator, @intCast(i)));
        }

        var code = try GKPCode.init(allocator, mode_count);
        errdefer code.deinit();

        const sp = @sqrt(math.pi);
        var vectors: [QuantumLatticeConfig.LATTICE_DEPTH][2]f64 = undefined;
        var kinds: [QuantumLatticeConfig.LATTICE_DEPTH]GateKind = undefined;
        for (0..QuantumLatticeConfig.LATTICE_DEPTH) |i| {
            const angle = @as(f64, @floatFromInt(i)) * 2.0 * math.pi / @as(f64, @floatFromInt(QuantumLatticeConfig.LATTICE_DEPTH));
            vectors[i] = [2]f64{ sp * @cos(angle), sp * @sin(angle) };
            kinds[i] = switch (i % 4) {
                0 => GateKind.lattice_x,
                1 => GateKind.lattice_z,
                2 => GateKind.lattice_cnot,
                else => GateKind.floquet_drive,
            };
        }

        const floquet = FloquetController.init(0.1, 5.0e9, 0.0, vectors, kinds);
        const verifier = QuantumAdvantageVerifier.initIteratedIndex(@max(@as(usize, 16), mode_count * 10));

        var graph = ReasoningGraph.init(allocator);
        errdefer graph.deinit();
        for (0..mode_count) |i| {
            try graph.addNode(ReasoningNode{
                .id = @intCast(i),
                .mode_id = @intCast(i),
                .energy = 0.0,
                .convergence = 1.0,
            });
        }
        var edge_serial: u64 = 5000;
        for (0..mode_count - 1) |i| {
            const src: u64 = @intCast(i);
            const dst: u64 = @intCast(i + 1);
            const src_mode: u32 = @intCast(i);
            const dst_mode: u32 = @intCast(i + 1);
            var seq: [2]QuantumLatticeGate = undefined;
            seq[0] = QuantumLatticeGate.beamSplitter(edge_serial + 1, src_mode, dst_mode, math.pi / 4.0, 0.0);
            seq[1] = QuantumLatticeGate.latticeCnot(edge_serial + 2, src_mode, dst_mode, QuantumLatticeConfig.CNOT_COUPLING);
            try graph.addEdge(ReasoningEdge{
                .id = edge_serial,
                .source = src,
                .target = dst,
                .weight = 1.0,
                .correlation = C64.init(1.0, 0.0),
                .fractal_dimension = 2.0,
                .sequence = seq,
            });
            edge_serial += 10;
        }

        return Self{
            .allocator = allocator,
            .modes = modes,
            .code = code,
            .floquet = floquet,
            .verifier = verifier,
            .graph = graph,
            .total_operations = 0,
            .error_correction_cycles = 0,
            .quantum_advantage_reported = false,
            .logical_error_rate = 1.0,
        };
    }

    pub fn deinit(self: *Self) void {
        for (self.modes.items) |*m| m.deinit();
        self.modes.deinit();
        self.code.deinit();
        self.graph.deinit();
    }

    pub fn executeQuantumReasoningCycle(self: *Self) f64 {
        self.floquet.executeSinglePeriod(self.modes.items);
        self.total_operations += @as(u64, @intCast(self.modes.items.len * QuantumLatticeConfig.LATTICE_DEPTH));

        for (0..self.activeModeCount()) |i| {
            const paired: u32 = @intCast(i);
            _ = paired;
        }

        const corrected = self.performErrorCorrection();
        self.error_correction_cycles += corrected;

        const energy = self.computeGraphEnergy();
        self.updateGraph(energy) catch {
            self.logical_error_rate = 1.0;
        };

        if (self.error_correction_cycles % 10 == 0) {
            self.quantum_advantage_reported = self.verifier.verify(.bosonic_sampling);
        }

        const total_gates = @as(f64, @floatFromInt(@max(self.total_operations, 1)));
        self.logical_error_rate = 1.0 - math.pow(f64, QuantumLatticeConfig.GATE_FIDELITY_TARGET, total_gates);
        return energy;
    }

    fn activeModeCount(self: *const Self) usize {
        return self.modes.items.len;
    }

    fn performErrorCorrection(self: *Self) u64 {
        var applied: u64 = 0;
        for (self.code.correct.gates.items) |gate| {
            const idx: usize = @intCast(gate.targets[0]);
            if (idx >= self.modes.items.len) continue;
            if (!self.modes.items[idx].anySyndrome()) continue;
            applyGate(self.modes.items, gate, 0.0);
            self.modes.items[idx].resetSyndrome();
            applied += 1;
        }
        for (self.modes.items) |*m| {
            m.x_correction_total = 0.0;
            m.p_correction_total = 0.0;
        }
        return applied;
    }

    fn computeGraphEnergy(self: *Self) f64 {
        var sum: f64 = 0.0;
        var count: f64 = 0.0;
        for (self.modes.items) |*m| {
            sum += m.photon_number * m.squeezing.re;
            count += 1.0;
        }
        var edge_iter = self.graph.edges.iterator();
        while (edge_iter.next()) |entry| {
            const e = entry.value_ptr;
            sum += e.weight * e.fractal_dimension;
            sum += e.correlation.magnitude();
            count += 1.0;
        }
        if (count > 0.0) {
            return sum / count;
        }
        return 1.0e6;
    }

    fn updateGraph(self: *Self, energy: f64) !void {
        for (0..self.modes.items.len) |i| {
            const node_id: u64 = @intCast(i);
            if (self.graph.nodes.getPtr(node_id)) |node| {
                node.energy = self.modes.items[i].photon_number;
                node.convergence = @abs(node.energy - energy);
            }
        }
        var edge_iter = self.graph.edges.iterator();
        while (edge_iter.next()) |entry| {
            const e = entry.value_ptr;
            const src: usize = @intCast(e.source);
            const dst: usize = @intCast(e.target);
            if (src >= self.modes.items.len or dst >= self.modes.items.len) continue;
            const a = self.modes.items[src].displacement;
            const b = self.modes.items[dst].displacement;
            const corr = a.conjugate().mul(b);
            e.correlation = corr;
            const mag = corr.magnitude();
            e.weight = 0.9 * e.weight + 0.1 * @min(mag, 10.0);
            e.fractal_dimension = @max(1.0, @min(3.0, 1.0 + @log(1.0 + mag)));
            try self.modes.items[src].correlations.put(@intCast(dst), mag);
        }
    }

    pub fn runQuantumAdvantageBenchmark(self: *Self, max_cycles: usize) BenchmarkResult {
        var best_energy: f64 = math.inf(f64);
        const start = std.time.nanoTimestamp();
        var executed: usize = 0;
        while (executed < max_cycles) : (executed += 1) {
            const energy = self.executeQuantumReasoningCycle();
            if (energy < best_energy) {
                best_energy = energy;
            }
            if (energy < QuantumLatticeConfig.CONVERGENCE_THRESHOLD) {
                executed += 1;
                break;
            }
        }
        const finish = std.time.nanoTimestamp();
        const elapsed: u64 = @intCast(@max(finish - start, 1));
        const ops = @as(f64, @floatFromInt(self.total_operations));
        const elapsed_f = @as(f64, @floatFromInt(elapsed));
        return BenchmarkResult{
            .cycles_completed = executed,
            .best_energy = best_energy,
            .total_time_ns = elapsed,
            .total_operations = self.total_operations,
            .error_correction_cycles = self.error_correction_cycles,
            .quantum_advantage_reported = self.quantum_advantage_reported,
            .mean_gate_fidelity = math.pow(f64, QuantumLatticeConfig.GATE_FIDELITY_TARGET, ops),
            .operations_per_ns = ops / elapsed_f,
            .analytic_advantage_factor = self.verifier.advantage_factor,
            .coherence_preserved = self.floquet.coherence_preserved,
            .logical_error_rate = self.logical_error_rate,
        };
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const mode_count: usize = 32;
    var core = try QuantumLatticeJaideCore.init(allocator, mode_count);
    defer core.deinit();

    const result = core.runQuantumAdvantageBenchmark(64);

    std.debug.print("quantum lattice jaide core benchmark\n", .{});
    std.debug.print("active bosonic modes: {d}\n", .{mode_count});
    std.debug.print("cycles completed: {d}\n", .{result.cycles_completed});
    std.debug.print("best energy: {d:.6}\n", .{result.best_energy});
    std.debug.print("total wall time ns: {d}\n", .{result.total_time_ns});
    std.debug.print("total gate operations: {d}\n", .{result.total_operations});
    std.debug.print("error correction cycles: {d}\n", .{result.error_correction_cycles});
    std.debug.print("analytic advantage factor: {d:.3}\n", .{result.analytic_advantage_factor});
    std.debug.print("verifier separation marker: {}\n", .{result.quantum_advantage_reported});
    std.debug.print("mean gate fidelity: {d:.9}\n", .{result.mean_gate_fidelity});
    std.debug.print("classical simulation throughput ops per ns: {d:.6}\n", .{result.operations_per_ns});
    std.debug.print("coherence preserved: {}\n", .{result.coherence_preserved});
    std.debug.print("logical error rate: {d:.9}\n", .{result.logical_error_rate});
}

