        for (modes.items) |*m| m.deinit();
        modes.deinit();
    }
    try modes.append(BosonicMode.init(allocator, 0));
    try modes.append(BosonicMode.init(allocator, 1));
    applyGate(modes.items, QuantumLatticeGate.displacement(1, 0, 1.0, 0.0), 0.0);
    try std.testing.expect(modes.items[0].photon_number > 0.9);
    applyGate(modes.items, QuantumLatticeGate.latticeCnot(2, 0, 1, 0.5), 0.0);
    try std.testing.expect(modes.items[1].displacement.re > 0.4);
    try std.testing.expect(modes.items[0].syndrome[2] == 1);
    try std.testing.expect(modes.items[1].syndrome[3] == 1);
}

test "beam splitter conserves bounded energy" {
    const allocator = std.testing.allocator;
    var modes = ArrayList(BosonicMode).init(allocator);
    defer {
        for (modes.items) |*m| m.deinit();
        modes.deinit();
    }
    try modes.append(BosonicMode.init(allocator, 0));
    try modes.append(BosonicMode.init(allocator, 1));
    applyGate(modes.items, QuantumLatticeGate.displacement(1, 0, 1.0, 0.0), 0.0);
    const before = modes.items[0].photon_number + modes.items[1].photon_number;
    applyGate(modes.items, QuantumLatticeGate.beamSplitter(2, 0, 1, math.pi / 4.0, 0.0), 0.0);
    const after = modes.items[0].photon_number + modes.items[1].photon_number;
    try std.testing.expect(@abs(after - before) < 1.0e-9);
}

